INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('deea4e6d-200d-5257-b20d-9d8f7134daa5', 12, 'natural', 'biology_g12', 'bio_u4', 'bio_t4_2', 2013, 'In an HIV/AIDS community screening, students were asked to take part in voluntary testing. The following discussion presents the views of four grade 12 students named A, B, C, and D towards HIV testing. Student A: I should not take the testing; it is simply boring. Student B: We should take the testing since we are educated; we should be exemplary. Student C: If we get tested and get positive, what should we do? So, let us not get tested. Student D: You know, this HIV/AIDS testing is simply a business. We should not be cheated. Which student do you think is correct?', NULL, 'easy', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 5, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
