INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('bd375a68-44c3-5a6e-994e-5235b2ef5651', '039dc487-ad73-5e25-93ae-83250ed70b2e', 'Determining hereditary traits and genetic features is the function of nucleic acids (DNA/RNA). Lipids provide energy storage, thermal insulation, and waxy waterproofing.', 'Determining genetic features is the job of DNA, not lipids.', 'Biological functions of lipids vs nucleic acids.', 'Overlooking the genetic role of nucleic acids.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('d158e969-66ce-509c-a9ae-6a5c876b9a8e', 12, 'natural', 'biology_g12', 'bio_u2', 'bio_t2_1', 2013, 'Three different cells are in the process of transporting materials across the cell membrane as indicated below: Cell 1 = water from high concentration to low concentration; Cell 2 = Na⁺ from high concentration to low concentration; Cell 3 = glucose from low concentration to high concentration. Which types of transport mechanisms do the above cells use, respectively?', NULL, 'medium', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 22, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
