INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('c7c98568-360d-59b1-a000-8513064353d1', 'd158e969-66ce-509c-a9ae-6a5c876b9a8e', 'Water moving down its gradient across a semipermeable membrane is Osmosis. Na+ ions moving down gradient via protein channels is Facilitated Diffusion. Glucose moving against gradient requiring ATP is Active Transport.', 'Water down gradient = Osmosis; Na+ down gradient = Facilitated diffusion; Glucose against gradient = Active transport.', 'Membrane transport mechanisms: Passive vs Active transport.', 'Confusing facilitated diffusion with active transport against a gradient.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('a1a30ac1-2579-5bae-a1e4-c956c97a077a', 12, 'natural', 'biology_g12', 'bio_u2', 'bio_t2_1', 2013, 'Suppose you took a container and divided it into two halves by a membrane which is permeable to water and labeled the two halves as A and B. Finally, you added hypertonic solution in A and hypotonic solution in B. What will be the expected result of this experiment?', NULL, 'easy', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 23, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
