INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('addb142f-f327-510b-b1d1-de0f62287e1e', 'a1a30ac1-2579-5bae-a1e4-c956c97a077a', 'Water moves by osmosis from a region of higher water potential (hypotonic solution in B) to lower water potential (hypertonic solution in A), causing water level in A to rise.', 'Water flows by osmosis from hypotonic B into hypertonic A, causing water level in A to rise.', 'Osmotic water movement and tonicity across semipermeable membranes.', 'Inverting osmotic flow direction from hypertonic to hypotonic.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
