INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('98498644-5c9e-5ac8-ad63-735119ba4a12', 12, 'natural', 'biology_g12', 'bio_u2', 'bio_t2_1', 2013, 'A class of grade 11 students were given two solutions A and B of unknown concentration separated by a semi-permeable membrane. The teacher instructed them to observe any changes in the water levels of the two solutions. After a few minutes, the students observed that the water level in solution A had decreased. What could the students conclude from their observation?', NULL, 'easy', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 23, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
