INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('7d5d0733-16c0-586a-93f7-bf4f1ca3f889', '98498644-5c9e-5ac8-ad63-735119ba4a12', 'Water always moves by osmosis from high water potential (less negative) to low water potential. Since water left chamber A, solution A must have had a higher water potential than B.', 'Water moved out of A into B, meaning solution A had higher water potential.', 'Water potential gradients and osmotic flow direction.', 'Assuming water moves toward higher water potential rather than away from it.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('800aa763-afc0-5c63-8af5-cdd6cc89b607', 12, 'natural', 'biology_g12', 'bio_u2', 'bio_t2_1', 2013, 'A student did an experiment and found out that catabolism of amino acid produces toxic ammonia in the liver cells, which gradually gets converted into urea and excreted through urine. What would be the result of the experiment if osmosis was blocked? The liver cells', NULL, 'medium', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 24, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
