INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('3fe32e91-75dc-5368-8e36-be3037627676', '4278c0d6-3b52-5378-a153-4ecddc2fbcbf', 'Below optimum temperature, molecules have lower thermal kinetic energy, leading to fewer effective collisions between enzyme active sites and substrates, forming fewer enzyme-substrate complexes per second.', 'Low temperatures decrease kinetic collisions, forming fewer enzyme-substrate complexes.', 'Temperature dependence of enzyme kinetics (kinetic collision theory).', 'Believing cold temperatures denature enzymes (cold slows kinetics; high heat denatures).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, source_name, source_page, package_id) VALUES ('43926dec-2cfb-59cb-b4d8-3f41a4b52b18', 12, 'natural', 'biology_g12', 'bio_u2', 'bio_t2_3', 2013, 'Cyclooxygenase-2 is an enzyme that catalyzes the conversion of arachidonic acid to prostaglandins, which promote pain and fever in our body. The painkiller ibuprofen acts as a non-competitive inhibitor of cyclooxygenase-2, reducing the production of prostaglandins. What would happen if the concentration of ibuprofen increased?', NULL, 'medium', 'published', 'ESSLCE Biology 2013 E.C. (2020-2021 G.C.) Booklet 12', 34, 'pkg_g12_biology_2013') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
