INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4170a3d5-ab2c-59ca-82aa-df98cbe0e268', '43926dec-2cfb-59cb-b4d8-3f41a4b52b18', 'C', 'Concentration of arachidonic acid is decreased.', NULL, false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
