INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('6b5bdb8f-f176-5e4e-aa2f-4373cc167df0', '43926dec-2cfb-59cb-b4d8-3f41a4b52b18', 'Increasing the concentration of ibuprofen (an inhibitor of COX-2) further suppresses prostaglandin synthesis, thereby reducing inflammatory fever and decreasing pain sensations in the body.', 'More ibuprofen blocks more COX-2, lowering prostaglandins and decreasing pain.', 'Enzyme inhibition pharmacology: NSAIDs and pain mediation.', 'Thinking higher inhibitor levels increase prostaglandin production.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
